  function nafsShare() {
    nafsCount("shared");
    try {
      if (navigator.share) { navigator.share({ title: "نَفَس", text: SHARE_TEXT, url: SHARE_URL }).catch(function () {}); return; }
    } catch (e) {}
    window.open("https://wa.me/?text=" + encodeURIComponent(SHARE_TEXT + " " + SHARE_URL), "_blank", "noopener");
  }
